-- ═══════════════════════════════════════════════════════════════
-- GREENERGY CRM — PRICE LIST & COSTED QUOTATIONS (v1)
-- Run AFTER workflow_v2.sql. Safe to re-run. Holds NO prices:
-- load them with the private supabase/pricing/pricing_seed.sql
-- (generated by supabase/build-pricing-seed.mjs; never committed).
--
-- pricing_config      'catalogue'  = supplier purchase prices (before GST)
--                     'cost_model' = profit %, GST %, size bands, structure,
--                                    installation and balance-of-system rates
-- pricing_history     every saved version (who, when, what)
-- quotation_costings  internal bill of materials, cost and margin per quotation
-- All list prices EXCLUDE GST; GST (8.9%) is added once, at the end of the price build-up.
-- Who can open the Price List: the CEO, plus anyone the CEO gives profiles.price_access:
--   'prices'            → may edit supplier prices (panels, inverters, batteries, cables, boxes, shed)
--   'prices_and_margin' → may also edit the cost model (profit %, GST %, bands, structure, installation)
-- Only CEO / admin manager can read per-quotation costings. Sales staff and customers
-- only ever see the selling price.
-- ═══════════════════════════════════════════════════════════════

create table if not exists pricing_config (
  key             text primary key check (key in ('catalogue', 'cost_model')),
  data            jsonb not null,
  version         integer not null default 1,
  updated_by      uuid references profiles(id),
  updated_by_name text,
  updated_at      timestamptz not null default now()
);

create table if not exists pricing_history (
  id              uuid default uuid_generate_v4() primary key,
  key             text not null,
  version         integer not null,
  data            jsonb not null,
  note            text,
  changed_by      uuid references profiles(id),
  changed_by_name text,
  created_at      timestamptz not null default now()
);

create table if not exists quotation_costings (
  quotation_id    uuid primary key references quotation_requests(id) on delete cascade,
  data            jsonb not null,
  catalogue_version integer,
  model_version   integer,
  updated_at      timestamptz not null default now()
);

-- Delegated price-list access (set by the CEO in User Management)
alter table profiles add column if not exists price_access text;
do $$ begin
  alter table profiles add constraint profiles_price_access_chk check (price_access in ('prices', 'prices_and_margin'));
exception when duplicate_object then null; end $$;

create or replace function can_edit_prices()
returns boolean language sql stable security definer set search_path = public as $$
  select is_admin() or exists (select 1 from profiles where id = auth.uid() and status = 'active' and price_access is not null);
$$;
create or replace function can_edit_margin()
returns boolean language sql stable security definer set search_path = public as $$
  select is_admin() or exists (select 1 from profiles where id = auth.uid() and status = 'active' and price_access = 'prices_and_margin');
$$;

-- Staff may edit their own contact details; only the CEO changes role, status or price access
drop policy if exists "Own profile update" on profiles;
create policy "Own profile update" on profiles for update using (id = auth.uid()) with check (id = auth.uid());

create or replace function profile_guard()
returns trigger language plpgsql set search_path = public as $$
begin
  if auth.uid() is null or is_admin() then return new; end if;
  if new.role is distinct from old.role or new.status is distinct from old.status
     or new.price_access is distinct from old.price_access or new.email is distinct from old.email
     or new.approved_by is distinct from old.approved_by then
    raise exception 'Only the CEO can change role, status or price-list access.';
  end if;
  return new;
end;$$;
drop trigger if exists trg_profile_guard on profiles;
create trigger trg_profile_guard before update on profiles
  for each row execute function profile_guard();

alter table pricing_config     enable row level security;
alter table pricing_history    enable row level security;
alter table quotation_costings enable row level security;

drop policy if exists "CEO reads price list" on pricing_config;
drop policy if exists "Price editors read price list" on pricing_config;
create policy "Price editors read price list" on pricing_config for select using (can_edit_prices());
drop policy if exists "CEO reads price history" on pricing_history;
drop policy if exists "Price editors read price history" on pricing_history;
create policy "Price editors read price history" on pricing_history for select using (can_edit_prices());
drop policy if exists "Managers read costings" on quotation_costings;
create policy "Managers read costings" on quotation_costings for select using (is_manager());
-- No insert/update policies: the server writes these with the service role after checking
-- can_edit_prices() / can_edit_margin() for the signed-in user.

-- What was quoted (shown to staff and the customer)
alter table quotation_requests add column if not exists panel_brand      text;
alter table quotation_requests add column if not exists panel_wp         integer;
alter table quotation_requests add column if not exists panel_count      integer;
alter table quotation_requests add column if not exists inverter_brand   text;
alter table quotation_requests add column if not exists inverter_label   text;
alter table quotation_requests add column if not exists inverter_kw      numeric;
alter table quotation_requests add column if not exists system_phase     integer;
alter table quotation_requests add column if not exists battery_label    text;
alter table quotation_requests add column if not exists battery_qty      integer;
alter table quotation_requests add column if not exists priced_from_list boolean not null default false;
alter table quotation_requests add column if not exists price_list_month text;

-- The specification locks together with the price after CEO approval
create or replace function quotation_spec_guard()
returns trigger language plpgsql set search_path = public as $$
begin
  if auth.uid() is null then return new; end if;
  if not (quotation_editable(new.status) or (quotation_editable(old.status) and new.status = 'owner_approval_pending')) and (
       new.panel_brand is distinct from old.panel_brand or new.panel_wp is distinct from old.panel_wp
    or new.panel_count is distinct from old.panel_count or new.inverter_brand is distinct from old.inverter_brand
    or new.inverter_label is distinct from old.inverter_label or new.inverter_kw is distinct from old.inverter_kw
    or new.battery_label is distinct from old.battery_label or new.battery_qty is distinct from old.battery_qty
    or new.priced_from_list is distinct from old.priced_from_list) then
    raise exception 'The specification is locked after approval. Use "Revise" — the CEO must approve the new version.';
  end if;
  return new;
end;$$;

drop trigger if exists trg_quotation_spec_guard on quotation_requests;
create trigger trg_quotation_spec_guard before update on quotation_requests
  for each row execute function quotation_spec_guard();
